package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.singlecell.SoupXAmbient;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Typed original ambient estimation/correction with owned execution and atomic complete-output admission. */
public final class SoupXWorkflowCli {
    private SoupXWorkflowCli() { }
    static final String SCOPE="Original source-bound SoupX1.6.2 or recovered1.3.0 ambient RNA estimation and optional count correction. Native Java validates complete literal inputs, exact integer counts, the declared raw-subset relation, strict-range soup profiles, original masks/exposures, fixed rho, complete automatic gene/cluster statistics, marker frequencies, recorded posterior-grid selection, corrected coordinate bounds and coherent17-digit TSV/Matrix Market transports. Global GLM estimates and confidence intervals, automatic gamma posteriors/density fitting, R RNG and original correction algorithms stay upstream; they are not independently refitted. Source package versions and every captured R function body/formals are checked, not every dependency/native binary or a paper's historical environment. No cell calling, clustering, biological non-expression annotation or no-ambient conclusion is inferred. Logical resource bounds are not process RAM/disk quotas; output_bytes bounds worker growth before admitted copies.";
    static final String ACTION="Require exit0 and result_admitted=true. Read WARNINGS.md, analysis-status.json, provenance.json, worker/worker-report.json, each source-status.json and original stdout/stderr. SKIP3: provide the exact permitted Windows Java/R4.6.1/selected SoupX/private-library and pinned original source profile, or skip dependent analysis. Analysis installs nothing or substitutes a release. FAIL2: no result from the atomic batch is admitted, including earlier completed cases. Preserve source objects, captured inputs, warnings and unadmitted-partial-results. Correct the named input/runtime/source/model/numerical-boundary/capacity cause and retry NEW paths. Do not repair IDs, drop observations, sum duplicate coordinates, recode NA/NaN/Inf, clip rho/counts, silently change ranges or substitute the analytical MLE for the original GLM. Biological marker/mask assumptions and interpretation remain caller decisions.";
    private record Captured(Path original,Path copy,NextflowFiles.Pin pin){void verify()throws IOException{require(pin.equals(NextflowFiles.pin(original,pin.bytes(),()->{}))&&pin.equals(NextflowFiles.pin(copy,pin.bytes(),()->{})),"Original/captured input changed: "+original);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.SoupXWorkflowCli --request request.json\nRequire schema_version1, mode AMBIENT, version1.6.2|1.3.0, count_units raw-integer-counts, matrix_format matrix-market|dense-tsv, clusters supplied|none, counts_relation raw-subset|supplied-independent, raw_counts, filtered_counts, gene_metadata(gene_id), droplet_metadata(droplet_id), cell_metadata(cell_id[,cluster]), soup_range(strict endpoints), soup_source(exact original tree), analyses, NEW out, rscript, r_home and r_libraries. Optional gene_sets(gene_set,gene_id), nonexpression_mask(cell_id,gene_set,non_expressing), rho_by_cell(cell_id,rho) are required exactly when used. Mask rows are complete cell-major/gene-set order and literal true/false; rho follows cell order. Literal UTF-8 TSV; no identifiers or observations are repaired.\nEvery case declares portable id, seed, estimation and adjustment object or explicit null. Estimation kinds: fixed; manual-global-poisson; automatic-gamma(1.6.2); automatic-legacy-density(1.3.0). The legacy table requires explicit apply_density_mode=true before correction; no API translation. Current-only force_accept and historical-only cell_specific=false are version checked. Correction declares method subtraction|soupOnly|multinomial, clustering_scope cell-only|supplied-clusters, round_to_integer, tolerance,p_cut. No arbitrary scripts/formulas/input RDS or runtime installs. Full field definitions are in SoupXWorkflowRequest and the workflow guide.\n"+SCOPE+"\n"+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Require --request UTF8_JSON or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();var sourcePin=NextflowFiles.pin(source,1048576,()->{});byte[] raw=NextflowFiles.bytes(source,1048576);require(raw.length==sourcePin.bytes()&&NextflowFiles.sha(raw).equals(sourcePin.sha256()),"Request changed during intake");var r=SoupXWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),source.getParent());var protectedPaths=new ArrayList<>(r.libraries());protectedPaths.add(r.rHome());protectedPaths.add(r.source());Path out=resolved(r.out());for(Path p:protectedPaths){Path path=resolved(p);require(!out.startsWith(path)&&!path.startsWith(out),"Output cannot overlap R home, libraries or original source, including aliases");}int[] exit={0};
            FollowupSupport.externalTransaction(Map.of("out",r.out().toString()),"original-soupx-ambient-development",(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);
                try{
                    verify(source,sourcePin);Files.write(stage.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());Path inputs=Files.createDirectory(stage.resolve("inputs"));var names=new ArrayList<Map.Entry<Path,String>>();names.add(Map.entry(r.rawCounts(),"raw-counts"));names.add(Map.entry(r.filteredCounts(),"filtered-counts"));names.add(Map.entry(r.genes(),"genes.tsv"));names.add(Map.entry(r.droplets(),"droplets.tsv"));names.add(Map.entry(r.cells(),"cells.tsv"));if(r.geneSets()!=null)names.add(Map.entry(r.geneSets(),"gene-sets.tsv"));if(r.mask()!=null)names.add(Map.entry(r.mask(),"nonexpression-mask.tsv"));if(r.perCellRho()!=null)names.add(Map.entry(r.perCellRho(),"rho-by-cell.tsv"));var captured=new ArrayList<Captured>();long remaining=r.inputBytes();for(var e:names){Captured c=capture(e.getKey(),inputs.resolve(e.getValue()),remaining);remaining-=c.pin.bytes();captured.add(c);}var nativeBudget=new SoupXAmbient.Budget(r.auditOperations());var population=SoupXWorkflowInputs.validate(inputs,r,nativeBudget);var meter=new SoupXWorkflowTransport.Meter(r.auditOperations());meter.spend(nativeBudget.used());
                    if(r.relation().equals("supplied-independent"))warnings.add("COUNT RELATION REVIEW: filtered counts are explicitly declared independent of the supplied raw-droplet matrix. Matching gene axes are checked; count equality, channel identity and biological suitability are not inferred.");
                    var filteredIds=new HashSet<>(population.filtered().cells());var overlap=new ArrayList<String>();for(String id:population.profile().selectedDroplets())if(filteredIds.contains(id))overlap.add(id);if(!overlap.isEmpty())warnings.add("PROFILE RANGE REVIEW: "+overlap.size()+" selected profile droplets also appear in the filtered-cell axis. The explicit range is preserved and no independent empty-droplet calling is performed. Review those IDs in provenance; they are not silently removed.");
                    manifest.put("source_request_sha256",sourcePin.sha256());var inputPins=new LinkedHashMap<String,Object>();for(Captured c:captured)inputPins.put(c.copy.getFileName().toString(),Map.of("bytes",c.pin.bytes(),"sha256",c.pin.sha256()));manifest.put("captured_inputs",inputPins);Path worker=Files.createDirectory(stage.resolve("worker"));NextflowFiles.writeJson(worker.resolve("parameters.json"),r.parameters());SoupXWorkflowRuntime.sources(stage,r,false);SoupXWorkflowRuntime.run(stage,r,manifest);var original=SoupXWorkflowTransport.read(worker.resolve("worker-report.json"),r);require(text(original.get("status")).equals("completed-with-warnings")&&bool(original.get("source_bodies_and_formals_checked_before_and_after")),"Original function guard/status incomplete");var guards=strings(original.get("guarded_functions"),10000);require(guards.size()==new HashSet<>(guards).size()&&guards.containsAll(List.of("SoupChannel","estimateSoup","setClusters","setContaminationFraction","estimateNonExpressingCells","calculateContaminationFraction","autoEstCont","adjustCounts","quickMarkers","expandClusters")),"Original essential function guard set incomplete");require(list(original.get("cases")).size()==r.analyses().size(),"Original case population differs");diagnostics(original,warnings,"worker");
                    for(Captured c:captured)c.verify();verify(source,sourcePin);SoupXWorkflowRuntime.sources(stage,r,true);SoupXWorkflowAudit.constructed(worker,population,r,meter);var reports=new ArrayList<Map<String,Object>>();for(var a:r.analyses()){Path target=worker.resolve("cases").resolve(text(a.get("id")));var report=SoupXWorkflowAudit.analysis(target,a,population,r,meter);reports.add(report);diagnostics(SoupXWorkflowTransport.read(target.resolve("source-status.json"),r),warnings,text(a.get("id")));if(((Number)report.get("original_nonfinite_metadata_fields_retained")).longValue()>0)warnings.add("ORIGINAL NONFINITE METADATA ["+a.get("id")+"]: "+report.get("original_nonfinite_metadata_fields_retained")+" fields retained, including any unbounded original confidence limits. Inspect metadata tokens/kinds; they are not replaced or independently refitted.");if(report.containsKey("original_minus_analytical")&&((Number)report.get("original_minus_analytical")).doubleValue()!=0)warnings.add("ORIGINAL GLM ITERATION ["+a.get("id")+"]: original rho="+report.get("original_GLM_rho_retained")+", analytical diagnostic="+report.get("analytical_Poisson_rho_diagnostic")+", score="+report.get("original_score_diagnostic")+". The original value is retained; convergence is not bitwise identity with the analytical limit.");}
                    Path results=Files.createDirectory(stage.resolve("results"));for(var a:r.analyses())copyTree(worker.resolve("cases").resolve(text(a.get("id"))),results.resolve(text(a.get("id"))));for(Captured c:captured)c.verify();verify(source,sourcePin);SoupXWorkflowRuntime.sources(stage,r,true);var provenance=new LinkedHashMap<String,Object>();provenance.put("version",r.version());provenance.put("source_request_sha256",sourcePin.sha256());provenance.put("captured_inputs",inputPins);provenance.put("selected_profile_droplets",population.profile().selectedDroplets());provenance.put("profile_droplets_also_in_filtered_cells",overlap);provenance.put("empty_droplet_cell_calling_performed",false);provenance.put("selected_soup_UMIs",population.profile().total());provenance.put("native_audit_operations",meter.used);provenance.put("analyses",reports);provenance.put("paper_parameters_or_biology_inferred",false);provenance.put("original_automatic_fits_or_count_correction_independently_refitted",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);state.put("status","PASS_ORIGINAL_SOUPX_AMBIENT_WORKFLOW");state.put("result_admitted",true);state.put("analyses",reports.size());
                }catch(SoupXWorkflowRuntime.Unavailable unavailable){exit[0]=3;state.put("status","SKIP3_DEPENDENCY_UNAVAILABLE");state.put("cause",unavailable.toString());warnings.add("SKIP3: DEPENDENT ANALYSIS SKIPPED. "+unavailable);quarantine(stage);}
                catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; use a permitted heap/input capacity and retry NEW paths without dropping observations.");quarantine(stage);}
                state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });emit(exit[0]==0?output:error,(exit[0]==0?"Original SoupX analysis admitted: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+r.out());emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out().resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    private static Captured capture(Path original,Path copy,long remaining)throws IOException{require(remaining>=0,"Combined input byte capacity exceeded");var pin=NextflowFiles.pin(original,remaining,()->{});try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];long count=0;for(int n=in.read(buffer);n>=0;n=in.read(buffer)){require(n<=remaining-count,"Input grew beyond byte capacity");out.write(buffer,0,n);count+=n;}require(count==pin.bytes(),"Input size changed during capture");}var captured=new Captured(original,copy,pin);captured.verify();return captured;}
    private static void verify(Path source,NextflowFiles.Pin pin)throws IOException{require(pin.equals(NextflowFiles.pin(source,pin.bytes(),()->{})),"Request changed during analysis");}
    private static void diagnostics(Map<String,Object> record,List<String> warnings,String id)throws IOException{for(String field:List.of("warnings","messages"))for(Object raw:list(record.get(field)))warnings.add("ORIGINAL "+field.toUpperCase(Locale.ROOT)+" ["+id+"]: "+text(raw));}
    private static void copyTree(Path from,Path to)throws IOException{require(Files.isDirectory(from,LinkOption.NOFOLLOW_LINKS),"Missing original case outputs");Files.createDirectory(to);try(var paths=Files.walk(from)){for(Path path:paths.toList()){if(path.equals(from))continue;require(!Files.isSymbolicLink(path),"Linked original output refused");Path target=to.resolve(from.relativize(path));if(Files.isDirectory(path,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(target);else{require(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS),"Nonregular original output refused");Files.copy(path,target);}}}}
    private static void quarantine(Path stage)throws IOException{Path from=stage.resolve("results").toAbsolutePath().normalize(),to=stage.resolve("unadmitted-partial-results").toAbsolutePath().normalize();require(from.getParent().equals(stage.toAbsolutePath().normalize())&&to.getParent().equals(from.getParent()),"Unsafe result quarantine path");if(Files.exists(from))Files.move(from,to);}
    private static Path resolved(Path path)throws IOException{var missing=new ArrayDeque<Path>();Path current=path.toAbsolutePath().normalize();while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"No existing path ancestor");missing.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path name:missing)current=current.resolve(name);return current.normalize();}
    private static void emit(PrintStream stream,String value){byte[] raw=(value+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
